'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
class Node{
 constructor(tag,doc){this.tagName=tag.toUpperCase();this.doc=doc;this.children=[];this.dataset={};this.attributes={};this.className='';this.value='';this.hidden=false;this.open=false;this.scrollTop=0;this.scrollLeft=0;this.clientWidth=200;this.clientHeight=200;this.scrollWidth=200;this.scrollHeight=200;this.listeners={};this.isConnected=true;this.style={setProperty(){}};this.textContent='';}
 append(...nodes){for(const n of nodes){n.parent=this;this.children.push(n);}}prepend(...nodes){for(const n of nodes)n.parent=this;this.children.unshift(...nodes);}replaceChildren(...nodes){this.children=[];this.append(...nodes);}remove(){if(this.parent)this.parent.children=this.parent.children.filter(n=>n!==this);this.isConnected=false;}
 setAttribute(k,v){this.attributes[k]=String(v);}getAttribute(k){return this.attributes[k]??null;}addEventListener(k,fn){(this.listeners[k]??=[]).push(fn);}fire(k,event={}){for(const fn of this.listeners[k]||[])fn(event);}focus(){this.doc.activeElement=this;}showModal(){this.open=true;}close(){this.open=false;this.fire('close');}
 matches(s){if(s==='*')return true;if(s.startsWith('.'))return this.className.split(' ').includes(s.slice(1));if(s==='[data-search-result]')return !!this.dataset.searchResult;return this.tagName.toLowerCase()===s;}
 querySelectorAll(s){return this.children.flatMap(n=>[...(s.split(',').some(v=>n.matches(v))?[n]:[]),...n.querySelectorAll(s)]);}querySelector(s){return this.querySelectorAll(s)[0]||null;}
}
function setup(){const document={activeElement:null};document.createElement=tag=>new Node(tag,document);document.body=new Node('body',document);const source=new Node('section',document);source.id='gear-diagrams';source.className='view';source.append(new Node('h1',document));source.children[0].textContent='White Orchard diagrams';const rail=new Node('nav',document);rail.scrollWidth=2000;rail.scrollLeft=777;source.append(rail);const entry=new Node('section',document);entry.id='diagram-viper';entry.className='view';entry.hidden=true;const host=new Node('article',document);host.className='reading-panel';entry.append(host);const views={'gear-diagrams':source,'diagram-viper':entry};document.getElementById=id=>views[id]||null;document.querySelector=s=>s==='.view:not([hidden])'?Object.values(views).find(v=>!v.hidden):null;document.querySelectorAll=()=>[];
 const events={},frames=[],location={hash:'#gear-diagrams',href:'https://example.test/#gear-diagrams'},stack=[{hash:location.hash,state:{}}];let at=0,restores=0,reopened=0;const fire=name=>(events[name]||[]).forEach(fn=>fn());const history={get state(){return stack[at].state;},replaceState(state,_,href){stack[at].state=state;if(href?.startsWith('#'))location.hash=href;},back(){at--;location.hash=stack[at].hash;Object.values(views).forEach(v=>v.hidden=v.id!==location.hash.slice(1));fire('phoenix:route-rendered');fire('popstate');}};
 const viewport={y:444,get scrollY(){return this.y;},scrollTo(x,y){this.y=y;},lock(){this.locked=true;},unlock(){this.locked=false;}};const storage=new Map(),writes=[];const localStorage={getItem:k=>storage.get(k)||null,setItem(k,v){writes.push(k);storage.set(k,v);}};const tasks={viper:{name:'Viper diagram',view:'diagram-viper',diagram:true,home:'hub-viper',intro:'steel sword'}},state={completed:{},progress:{}};
 const window={PHOENIX_MAP:{markers:[]},PHOENIX_EXPLORATION:{categories:[]},PhoenixViewport:viewport,innerHeight:844,PhoenixDiagramRoutes:{captureCurrent:()=>({hash:'#gear-diagrams',y:444,railX:777}),restoreCurrent(origin){restores++;rail.scrollLeft=origin.railX;viewport.y=origin.y;}}};const c={window,document,location,history,localStorage,requestAnimationFrame:fn=>frames.push(fn),addEventListener:(n,fn)=>(events[n]??=[]).push(fn)};vm.createContext(c);for(const f of ['search-model.js','search-ui.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);function navigate(hash){stack.splice(at+1);stack.push({hash,state:{}});at++;location.hash=hash;Object.values(views).forEach(v=>v.hidden=v.id!==hash.slice(1));viewport.y=0;fire('phoenix:route-rendered');}
 const api=window.createPhoenixSearch({tasks,state,engine:{},navigate}),trigger=new Node('button',document),dialog=document.body.querySelector('dialog'),input=dialog.querySelector('input'),results=dialog.querySelector('.guide-search-results');function flush(){for(let i=0;frames.length&&i<30;i++){const jobs=frames.splice(0);jobs.forEach(fn=>fn());}}return {api,dialog,input,results,rail,viewport,state,writes,trigger,flush,restores:()=>restores,reopened:()=>reopened,open(){api.open(trigger,{reopen(){reopened++;}});},query(q){input.value=q;input.fire('input');},pick(){results.querySelector('[data-search-result]').onclick();},back(){host.querySelector('.guide-search-return').onclick();}};}
test('choosing a result does not schedule a late source restore onto the destination page',()=>{const x=setup();x.open();x.query('Viper');x.pick();assert.equal(x.viewport.y,0);x.flush();assert.equal(x.viewport.y,0);assert.equal(x.restores(),0);assert.equal(x.viewport.locked,false);});
test('Return to Search restores query, list position, source rails and modal locking',()=>{const x=setup();x.open();x.query('Viper');x.results.scrollTop=321;x.pick();x.rail.scrollLeft=0;x.back();x.flush();assert.equal(x.dialog.open,true);assert.equal(x.input.value,'Viper');assert.equal(x.results.scrollTop,321);assert.equal(x.rail.scrollLeft,777);assert.equal(x.viewport.y,444);assert.equal(x.viewport.locked,true);});
test('closing Search reopens the menu on a later frame instead of its closing click',()=>{const x=setup();x.open();x.api.close();assert.equal(x.dialog.open,false);assert.equal(x.reopened(),0);x.flush();assert.equal(x.reopened(),1);assert.equal(x.viewport.locked,false);});
test('search history writes only its own record and leaves game progress unchanged',()=>{const x=setup(),before=JSON.stringify(x.state);x.open();x.query('Viper');x.pick();assert.deepEqual(x.writes,['phoenix.search.history.v1']);assert.equal(JSON.stringify(x.state),before);});

test('Escape closes Search once instead of merely clearing the search field',()=>{const x=setup();x.open();x.query('Viper');let prevented=false,stopped=false;x.dialog.fire('keydown',{key:'Escape',preventDefault(){prevented=true;},stopPropagation(){stopped=true;}});assert.equal(x.dialog.open,false);assert.equal(prevented,true);assert.equal(stopped,true);x.flush();assert.equal(x.reopened(),1);});
